import sys
import json

def evaluate(line):
    try:
        data = json.loads(line)
        sources = {s['id']: s for s in data.get('sources', [])}
        memories = {m['id']: m for m in data.get('memories', [])}
        registry = {r['plugin_id']: r for r in data.get('registry', [])}
        credentials = {c['id']: c for c in data.get('credentials', [])}
        approvals = {a['id']: a for a in data.get('approvals', [])}
        req = data.get('request', {})

        plugin_id = req.get('plugin_id')
        if not plugin_id: return {"decision": "deny", "reasons": ["missing plugin_id"]}

        # 1. Plugin registry checks
        reg = registry.get(plugin_id)
        if not reg: return {"decision": "deny", "reasons": ["no registry entry"]}
        if reg.get('status') != 'active': return {"decision": "deny", "reasons": ["inactive registry"]}
        if reg.get('catalog_trust') != 'signed': return {"decision": "deny", "reasons": ["unsigned registry"]}
        if not reg.get('catalog_signature_valid'): return {"decision": "deny", "reasons": ["invalid catalog signature"]}
        if req.get('capability') != reg.get('capability'): return {"decision": "deny", "reasons": ["capability mismatch"]}

        # 2. Credential checks
        cred_id = req.get('credential_id')
        cred = credentials.get(cred_id)
        if not cred: return {"decision": "deny", "reasons": ["missing credential"]}
        if cred.get('status') != 'active': return {"decision": "deny", "reasons": ["inactive credential"]}
        if plugin_id not in cred.get('plugin_ids', []): return {"decision": "deny", "reasons": ["credential not bound"]}
        req_scopes = set(reg.get('required_scopes', []))
        cred_scopes = set(cred.get('scopes', []))
        if not req_scopes.issubset(cred_scopes): return {"decision": "deny", "reasons": ["insufficient scopes"]}

        # 3. Destinations checks
        allowed_hosts = reg.get('allowed_hosts', [])
        req_destinations = req.get('destinations', [])
        if not req_destinations: return {"decision": "deny", "reasons": ["no destinations"]}
        if req_destinations[0] != req.get('target'): return {"decision": "deny", "reasons": ["target mismatch"]}

        for dest in req_destinations:
            matched = False
            for ah in allowed_hosts:
                if ah.startswith('*.'):
                    if dest.endswith(ah[1:]):
                        matched = True
                        break
                else:
                    if dest == ah:
                        matched = True
                        break
            if not matched: return {"decision": "deny", "reasons": ["destination not allowed"]}

        # 4. Memory lineage and cycle check
        def has_cycle(mem_ids, visited, stack):
            for m in mem_ids:
                if m in stack: return True
                if m in visited: continue
                visited.add(m)
                stack.add(m)
                mem = memories.get(m)
                if not mem: return True
                if has_cycle(mem.get('parent_memory_ids', []), visited, stack):
                    return True
                stack.remove(m)
            return False

        visited_cycle = set()
        stack = set()
        if has_cycle(req.get('memory_ids', []), visited_cycle, stack):
            return {"decision": "deny", "reasons": ["cycle or unresolved parent in memories"]}

        roots = set()
        for mid in visited_cycle:
            mem = memories.get(mid)
            if mem.get('status') != 'active': return {"decision": "deny", "reasons": ["inactive memory"]}
            for sid in mem.get('source_ids', []):
                src = sources.get(sid)
                if not src: return {"decision": "deny", "reasons": ["missing source"]}
                if src.get('status') != 'active': return {"decision": "deny", "reasons": ["inactive source"]}
                roots.add(sid)

        risk = reg.get('risk')
        if risk == 'high':
            for sid in roots:
                src = sources.get(sid)
                if src.get('trust') != 'signed': return {"decision": "deny", "reasons": ["unsigned root source"]}
                if not src.get('signature_valid'): return {"decision": "deny", "reasons": ["invalid signature on source"]}

        # 5. Approvals check
        if risk == 'high':
            app_id = req.get('approval_id')
            if not app_id: return {"decision": "deny", "reasons": ["missing high-risk approval"]}
            app = approvals.get(app_id)
            if not app: return {"decision": "deny", "reasons": ["missing approval"]}
            if app.get('status') != 'active': return {"decision": "deny", "reasons": ["inactive approval"]}
            if app.get('type') != 'change_ticket': return {"decision": "deny", "reasons": ["wrong approval type"]}
            if app.get('plugin_id') != plugin_id: return {"decision": "deny", "reasons": ["approval plugin mismatch"]}
            if app.get('capability') != req.get('capability'): return {"decision": "deny", "reasons": ["approval capability mismatch"]}
            if app.get('target') != req.get('target'): return {"decision": "deny", "reasons": ["approval target mismatch"]}
            if app.get('args_digest') != req.get('args_digest'): return {"decision": "deny", "reasons": ["approval digest mismatch"]}

        if risk == 'low':
            app_id = req.get('approval_id')
            if app_id:
                app = approvals.get(app_id)
                if not app: return {"decision": "deny", "reasons": ["missing low-risk approval"]}
                if app.get('status') != 'active': return {"decision": "deny", "reasons": ["inactive low-risk approval"]}

        # 6. Raw credential forwarding check
        if req.get('forwards_credential'):
            return {"decision": "deny", "reasons": ["forwards credential"]}

        return {"decision": "allow", "reasons": ["all checks passed"]}

    except Exception as e:
        return {"decision": "deny", "reasons": ["exception"]}

for line in sys.stdin:
    line = line.strip()
    if not line: continue
    print(json.dumps(evaluate(line)))
